function projectsPage(error = '', name = '', filter = 'Active') {
  return page('Projects', `<h1>Workboard</h1>
    ${error ? `<div role="alert">${escapeHtml(error)}</div>` : ''}
    <form action="/projects" method="post">
      <label for="project-name">Project name</label>
      <input id="project-name" name="name" type="text" value="${escapeHtml(name)}">
      <button type="submit">Create project</button>
    </form>
    <form action="/" method="get">
      <label for="project-filter">Project filter</label>
      <select id="project-filter" name="filter" onchange="this.form.requestSubmit()">
        <option${filter === 'Active' ? ' selected' : ''}>Active</option>
        <option${filter === 'Archived' ? ' selected' : ''}>Archived</option>
      </select>
    </form>
    <section aria-label="Projects">${listProjects.all(filter === 'Archived' ? 1 : 0).map(project => `
      <div class="project-row" data-testid="project-row">
        <span>${escapeHtml(project.name)}</span>
        <span data-testid="project-summary">${project.completed}/${project.total} completed</span>
        <form action="/projects/${project.id}" method="get"><button type="submit">Open project</button></form>
        <form action="/projects/${project.id}/${project.archived ? 'restore' : 'archive'}" method="post">
          <button type="submit">${project.archived ? 'Restore project' : 'Archive project'}</button>
        </form>
      </div>`).join('')}</section>`);
}

function projectPage(project, error = '') {
  return page(project.name, `<h1>${escapeHtml(project.name)}</h1>
    <form action="/" method="get"><button type="submit">Projects</button></form>
    ${project.archived ? '<p>Archived project</p>' : ''}
    <div role="alert" id="task-error">${escapeHtml(error)}</div>
    <form action="/projects/${project.id}/rename" method="post">
      <label for="new-project-name">New project name</label>
      <input id="new-project-name" name="name" type="text" value="${escapeHtml(project.name)}"${project.archived ? ' disabled' : ''}>
      <button type="submit"${project.archived ? ' disabled' : ''}>Rename project</button>
    </form>
    <form action="/projects/${project.id}/tasks" method="post">
      <label for="task-title">Task title</label>
      <input id="task-title" name="title" type="text">
      <button type="submit"${project.archived ? ' disabled' : ''}>Create task</button>
    </form>
    <label for="task-filter">Task filter</label>
    <select id="task-filter">
      <option>All</option><option>Open</option><option>Completed</option>
    </select>
    <section aria-label="Tasks">${listTasks.all(project.id).map(task => `
      <div class="task-row" data-testid="task-row">
        <input type="checkbox" aria-label="${escapeHtml(`Complete ${task.title}`)}"
          data-completion-url="/projects/${project.id}/tasks/${task.id}/completion"${task.completed ? ' checked' : ''}${project.archived ? ' disabled' : ''}>
        <span>${escapeHtml(task.title)}</span>
        <form action="/projects/${project.id}/tasks/${task.id}/rename" method="post" data-task-rename>
          <label for="new-task-title-${task.id}">New task title</label>
          <input id="new-task-title-${task.id}" name="title" type="text" value="${escapeHtml(task.title)}"${project.archived ? ' disabled' : ''}>
          <button type="submit"${project.archived ? ' disabled' : ''}>Rename task</button>
        </form>
      </div>`).join('')}</section>
    <script>
      const filter = document.getElementById('task-filter');
      function applyFilter() {
        document.querySelectorAll('[data-testid="task-row"]').forEach(row => {
          const completed = row.querySelector('input').checked;
          row.hidden = filter.value === 'Open' && completed || filter.value === 'Completed' && !completed;
        });
      }
      filter.addEventListener('change', applyFilter);
      document.querySelectorAll('[data-completion-url]').forEach(checkbox => {
        checkbox.addEventListener('change', async () => {
          const completed = checkbox.checked;
          checkbox.disabled = true;
          document.getElementById('task-error').textContent = '';
          try {
            const response = await fetch(checkbox.dataset.completionUrl, {
              method: 'POST', body: new URLSearchParams({ completed: String(completed) })
            });
            if (!response.ok) throw new Error('Completion update failed');
          } catch {
            checkbox.checked = !completed;
            document.getElementById('task-error').textContent = 'Could not save task completion. Please try again.';
          } finally {
            checkbox.disabled = false;
            applyFilter();
          }
        });
      });
    </script>
    <script>
      document.querySelectorAll('[data-task-rename]').forEach(form => {
        form.addEventListener('submit', async event => {
          event.preventDefault();
          const input = form.elements.title;
          const title = input.value.trim();
          const alert = document.getElementById('task-error');
          alert.textContent = '';
          if (!title) {
            alert.textContent = 'Task title is required';
            return;
          }
          const button = form.querySelector('button');
          button.disabled = true;
          try {
            const response = await fetch(form.action, {
              method: 'POST', body: new URLSearchParams({ title })
            });
            if (!response.ok) throw new Error('Rename failed');
            const row = form.closest('[data-testid="task-row"]');
            row.querySelector('span').textContent = title;
            row.querySelector('[data-completion-url]').setAttribute('aria-label', 'Complete ' + title);
            input.value = title;
          } catch {
            alert.textContent = 'Could not rename task. Please try again.';
          } finally {
            button.disabled = false;
          }
        });
      });
    </script>`);
}

async function readForm(req) {
  let body = '';
  for await (const chunk of req) {
    body += chunk;
    if (Buffer.byteLength(body) > 1024 * 1024) {
      const error = new Error('Request too large');
      error.status = 413;
      throw error;
    }
  }
  return new URLSearchParams(body);
}

function html(res, status, content) {
  res.writeHead(status, { 'Content-Type': 'text/html; charset=utf-8' });
  res.end(content);
}

const server = http.createServer(async (req, res) => {
  try {
    const url = new URL(req.url, 'http://localhost');
    if (req.method === 'GET' && url.pathname === '/health') {
      res.writeHead(200, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({ status: 'ok' }));
    } else if (req.method === 'GET' && url.pathname === '/') {
      html(res, 200, projectsPage('', '', url.searchParams.get('filter') === 'Archived' ? 'Archived' : 'Active'));
    } else if (req.method === 'POST' && url.pathname === '/projects') {
      const name = ((await readForm(req)).get('name') || '').trim();
      if (!name) {
        html(res, 422, projectsPage('Project name is required'));
        return;
      }
      createProject.run(name);
      res.writeHead(303, { Location: '/' });
      res.end();
    } else if (req.method === 'POST' && /^\/projects\/\d+\/(archive|restore)$/.test(url.pathname)) {
      const parts = url.pathname.split('/');
      const archived = parts[3] === 'archive';
      const result = setArchived.run(archived ? 1 : 0, Number(parts[2]));
      if (!result.changes) {
        html(res, 404, page('Not found', '<h1>Project not found</h1>'));
        return;
      }
      res.writeHead(303, { Location: archived ? '/' : '/?filter=Archived' });
      res.end();
    } else if (req.method === 'GET' && /^\/projects\/\d+$/.test(url.pathname)) {
      const project = findProject.get(Number(url.pathname.split('/')[2]));
      if (!project) {
        html(res, 404, page('Not found', '<h1>Project not found</h1><form action="/"><button>Projects</button></form>'));
        return;
      }
      html(res, 200, projectPage(project));
    } else if (req.method === 'POST' && /^\/projects\/\d+\/rename$/.test(url.pathname)) {
      const project = findProject.get(Number(url.pathname.split('/')[2]));
      if (!project) {
        html(res, 404, page('Not found', '<h1>Project not found</h1>'));
        return;
      }
      if (project.archived) {
        html(res, 403, projectPage(project, 'Archived projects cannot be changed'));
        return;
      }
      const name = ((await readForm(req)).get('name') || '').trim();
      if (!name) {
        html(res, 422, projectPage(project, 'Project name is required'));
        return;
      }
      renameProject.run(name, project.id);
      res.writeHead(303, { Location: `/projects/${project.id}` });
      res.end();
    } else if (req.method === 'POST' && /^\/projects\/\d+\/tasks(?:\/\d+\/(completion|rename))?$/.test(url.pathname)) {
      const parts = url.pathname.split('/');
      const project = findProject.get(Number(parts[2]));
      if (!project) {
        html(res, 404, page('Not found', '<h1>Project not found</h1>'));
        return;
      }
      if (project.archived) {
        html(res, 403, projectPage(project, 'Archived projects cannot be changed'));
        return;
      }
      const form = await readForm(req);
      if (parts.length === 4) {
        const title = (form.get('title') || '').trim();
        if (!title) {
          html(res, 422, projectPage(project, 'Task title is required'));
          return;
        }
        createTask.run(project.id, title);
        res.writeHead(303, { Location: `/projects/${project.id}` });
        res.end();
      } else if (parts[5] === 'rename') {
        const title = (form.get('title') || '').trim();
        if (!title) {
          html(res, 422, projectPage(project, 'Task title is required'));
          return;
        }
        const result = renameTask.run(title, Number(parts[4]), project.id);
        if (!result.changes) {
          html(res, 404, page('Not found', '<h1>Task not found</h1>'));
          return;
        }
        res.writeHead(303, { Location: `/projects/${project.id}` });
        res.end();
      } else {
        const completed = form.get('completed');
        if (completed !== 'true' && completed !== 'false') {
          html(res, 400, page('Invalid completion', '<h1>Invalid completion state</h1>'));
          return;
        }
        const result = updateTask.run(completed === 'true' ? 1 : 0, Number(parts[4]), project.id);
        res.writeHead(result.changes ? 204 : 404);
        res.end();
      }
    } else {
      html(res, 404, page('Not found', '<h1>Page not found</h1>'));
    }
  } catch (error) {
    if (error.status === 413) {
      html(res, 413, page('Request too large', '<h1>Request too large</h1>'));
    } else {
      console.error(error);
      html(res, 500, page('Server error', '<h1>Server error</h1>'));
    }
  }
});

server.listen(Number(process.env.PORT || 8080), '0.0.0.0', () => {
  console.log(`Workboard listening on port ${server.address().port}`);
});

for (const signal of ['SIGINT', 'SIGTERM']) {
  process.on(signal, () => server.close(() => {
    db.close();
    process.exit(0);
  }));
}

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { spawn } from 'node:child_process';
import { mkdtemp, rm } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { once } from 'node:events';
import { runInNewContext } from 'node:vm';
import { DatabaseSync } from 'node:sqlite';

test('archive migration, summaries, read-only tasks, restore and restart persistence', async () => {
  const directory = await mkdtemp(join(tmpdir(), 'workboard-archive-'));
  const dbPath = join(directory, 'workboard.sqlite');
  // Model a database from the previous checkpoint.
  const legacy = new DatabaseSync(dbPath);
  legacy.exec(`CREATE TABLE projects (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL);
    INSERT INTO projects (name) VALUES ('Existing project');`);
  legacy.close();
  let server;
  try {
    server = await start(dbPath);
    const post = (path, fields = {}) => fetch(`${server.base}${path}`, {
      method: 'POST', body: new URLSearchParams(fields), redirect: 'manual'
    });
    const get = path => fetch(`${server.base}${path}`).then(res => res.text());
    let active = await get('/');
    assert.match(active, /<label for="project-filter">Project filter<\/label>/);
    assert.match(active, /<option selected>Active<\/option>/);
    assert.match(active, /data-testid="project-summary">0\/0 completed/);
    await post('/projects', { name: 'Second project' });
    await post('/projects/1/tasks', { title: 'First task' });
    await post('/projects/1/tasks', { title: 'Second task' });
    await post('/projects/1/tasks/1/completion', { completed: 'true' });
    active = await get('/');
    assert.match(active, /data-testid="project-summary">1\/2 completed/);
    assert.match(active, /data-testid="project-summary">0\/0 completed/);
    assert.equal((await post('/projects/1/archive')).status, 303);
    assert.doesNotMatch(await get('/'), /Existing project/);
    let archived = await get('/?filter=Archived');
    assert.match(archived, /<option selected>Archived<\/option>/);
    assert.match(archived, /Existing project/);
    assert.match(archived, /data-testid="project-summary">1\/2 completed/);
    assert.match(archived, />Open project<\/button>/);
    assert.match(archived, />Restore project<\/button>/);
    assert.doesNotMatch(archived, /Second project|>Archive project<\/button>/);
    let detail = await get('/projects/1');
    assert.match(detail, /Archived project/);
    assert.match(detail, /<button type="submit" disabled>Create task/);
    assert.match(detail, /tasks\/1\/completion" checked disabled/);
    assert.match(detail, /tasks\/2\/completion" disabled/);
    // The same client filter continues to operate on disabled checkboxes.
    const filter = { value: 'All', addEventListener(type, handler) { this.change = handler; } };
    const rows = [true, false].map(checked => ({
      checkbox: { checked, disabled: true, addEventListener() {} },
      querySelector() { return this.checkbox; }, hidden: false
    }));
    runInNewContext(detail.match(/<script>([\s\S]*?)<\/script>/)[1], {
      document: {
        getElementById: () => filter,
        querySelectorAll: selector => selector === '[data-testid="task-row"]' ? rows : rows.map(row => row.checkbox)
      }
    });
    for (const [value, expected] of [['All', [false, false]], ['Open', [true, false]], ['Completed', [false, true]]]) {
      filter.value = value;
      filter.change();
      assert.deepEqual(rows.map(row => row.hidden), expected);
      assert.ok(rows.every(row => row.checkbox.disabled));
    }
    assert.equal((await post('/projects/1/tasks', { title: 'Blocked task' })).status, 403);
    assert.equal((await post('/projects/1/tasks/1/completion', { completed: 'false' })).status, 403);
    assert.equal(await get('/projects/1'), detail);
    await server.stop();
    server = await start(dbPath);
    assert.equal(await get('/?filter=Archived'), archived);
    assert.equal(await get('/projects/1'), detail);
    assert.equal((await post('/projects/1/restore')).status, 303);
    assert.doesNotMatch(await get('/?filter=Archived'), /data-testid="project-row"/);
    active = await get('/');
    assert.ok(active.indexOf('Existing project') < active.indexOf('Second project'));
    assert.match(active, /data-testid="project-summary">1\/2 completed/);
    detail = await get('/projects/1');
    assert.doesNotMatch(detail, /Archived project| disabled/);
    assert.match(detail, /tasks\/1\/completion" checked/);
    assert.equal((await post('/projects/1/tasks/2/completion', { completed: 'true' })).status, 204);
    assert.match(await get('/'), /data-testid="project-summary">2\/2 completed/);
    await server.stop();
    server = await start(dbPath);
    assert.match(await get('/'), /data-testid="project-summary">2\/2 completed/);
    assert.doesNotMatch(await get('/projects/1'), /Archived project| disabled/);
    assert.equal((await post('/projects/9999/archive')).status, 404);
  } finally {
    if (server) await server.stop();
    await rm(directory, { recursive: true, force: true });
  }
});

test('rename preserves identity, ordering, tasks and persistence; archived names are protected', async () => {
  const directory = await mkdtemp(join(tmpdir(), 'workboard-rename-'));
  const dbPath = join(directory, 'workboard.sqlite');
  let server;
  try {
    server = await start(dbPath);
    const post = (path, fields = {}) => fetch(`${server.base}${path}`, {
      method: 'POST', body: new URLSearchParams(fields), redirect: 'manual'
    });
    const get = path => fetch(`${server.base}${path}`).then(res => res.text());
    await post('/projects', { name: 'Original' });
    await post('/projects', { name: 'Second project' });
    await post('/projects/1/tasks', { title: 'Saved task' });
    await post('/projects/1/tasks/1/completion', { completed: 'true' });
    const original = await get('/projects/1');
    assert.match(original, /<label for="new-project-name">New project name<\/label>/);
    assert.match(original, /<button type="submit">Rename project<\/button>/);
    for (const name of ['', ' \t ']) {
      const response = await post('/projects/1/rename', { name });
      assert.equal(response.status, 422);
      assert.match(await response.text(), /role="alert"[^>]*>Project name is required/);
      assert.equal(await get('/projects/1'), original);
    }
    const response = await post('/projects/1/rename', { name: '  Renamed <&>  ' });
    assert.equal(response.status, 303);
    assert.equal(response.headers.get('location'), '/projects/1');
    const renamed = await get('/projects/1');
    assert.match(renamed, /<h1>Renamed &lt;&amp;&gt;<\/h1>/);
    assert.match(renamed, /tasks\/1\/completion" checked/);
    assert.match(renamed, /<span>Saved task<\/span>/);
    const list = await get('/');
    assert.ok(list.indexOf('Renamed &lt;&amp;&gt;') < list.indexOf('Second project'));
    assert.match(list, /data-testid="project-summary">1\/1 completed/);
    assert.match(list, /action="\/projects\/1"/);
    assert.doesNotMatch(list, /Original/);
    await server.stop();
    server = await start(dbPath);
    assert.equal(await get('/projects/1'), renamed);
    assert.equal(await get('/'), list);
    await post('/projects/1/archive');
    const archived = await get('/projects/1');
    assert.match(archived, /id="new-project-name"[^>]* disabled/);
    assert.match(archived, /<button type="submit" disabled>Rename project/);
    assert.equal((await post('/projects/1/rename', { name: 'Blocked' })).status, 403);
    assert.equal(await get('/projects/1'), archived);
    await post('/projects/1/restore');
    assert.equal(await get('/projects/1'), renamed);
    assert.equal((await post('/projects/1/rename', { name: 'Restored name' })).status, 303);
    await server.stop();
    server = await start(dbPath);
    assert.match(await get('/projects/1'), /<h1>Restored name<\/h1>/);
    assert.match(await get('/projects/1'), /tasks\/1\/completion" checked/);
    assert.match(await get('/'), /data-testid="project-summary">1\/1 completed/);
    assert.equal((await post('/projects/9999/rename', { name: 'Missing' })).status, 404);
  } finally {
    if (server) await server.stop();
    await rm(directory, { recursive: true, force: true });
  }
});

test('task rename preserves ownership, order, completion, filtering and persistence', async () => {
